class CommandLineParams:
    """Store command line parameters used by argparse module."""

    def __init__(self):
        self._params = {
            "v": {"dest": "debug", "action": "store_true", "help": "Verbose"},
            "ro": {
                "metavar": "Robot Output",
                "dest": "robot_output",
                "help": "XML output file from Robot Framework",
            },
            "tl": {
                "metavar": "Test line",
                "dest": "tl",
                "help": "Test line name, e.g., IAV_WRO_TL020",
            },
            "f": {
                "metavar": "Zipfile path",
                "dest": "zipfile_path",
                "help": "ZIP file with report",
            },
            "l": {"metavar": "Label", "dest": "label", "help": "TL Label"},
            "rr": {
                "metavar": "",
                "dest": "rr",
                "default": None,
                "type": str,
                "help": "RobotLTE repository revision",
            },
            "qc": {
                "metavar": "",
                "dest": "qc_config_file",
                "default": None,
                "help": "Path to QC configuration file",
            },
            "p": {
                "metavar": "",
                "dest": "phase",
                "default": None,
                "help": "Testing phase, e.g., QTp1",
            },
            "ca": {
                "metavar": "",
                "dest": "ca",
                "default": None,
                "help": "Competence area, e.g., CPLN",
            },
            "rp": {
                "metavar": "",
                "dest": "rp",
                "default": None,
                "help": "Reporting Portal URL",
            },
            "fe": {
                "metavar": "",
                "dest": "fe",
                "default": None,
                "type": str,
                "help": "Fish Eye Portal URL",
            },
            "type": {
                "metavar": "",
                "dest": "product_type",
                "default": "wmp",
                "type": str,
                "choices": ["wmp", "dcm"],
                "help": "Product type: wmp, dcm",
            },
            "load_prefix": {
                "metavar": "",
                "dest": "load_prefix",
                "default": None,
                "type": str,
                "help": "BTS SW LOAD prefix valid for DCM product where load is unknown in TargetBD file name",
            },
            "info": {
                "metavar": "",
                "dest": "info",
                "type": str,
                "help": "Additional information provided as part of each test",
            },
            "commits_link": {
                "metavar": "",
                "dest": "commits_link",
                "default": None,
                "type": str,
                "help": "Link to page with commits information",
            },
            "build_link": {
                "metavar": "",
                "dest": "build_link",
                "default": None,
                "type": str,
                "help": "Deprecated option. Please see log_link",
            },
            "log_link": {
                "metavar": "",
                "dest": "log_link",
                "default": None,
                "type": str,
                "help": "Link to build results (test logs)",
            },
            "execution_link": {
                "metavar": "",
                "dest": "execution_link",
                "default": None,
                "type": str,
                "help": "Link to cloud execution",
            },
            "startup_analysis_diagram_link": {
                "metavar": "",
                "dest": "startup_analysis_diagram_link",
                "default": None,
                "type": str,
                "help": "Link to startup analysis diagram",
            },
            "file_path": {
                "metavar": "suite",
                "dest": "suite",
                "default": "",
                "type": str,
                "help": "File path in repository, e.g., testsuite/demo/some_test.robot",
            },
            "sw_version": {
                "metavar": "",
                "dest": "sw_version",
                "default": None,
                "type": str,
                "help": "eNB software version in format:\n  * DNH0.0_ENB_2033939_1204\n  * DNH0.0_ENB_2033939_1204:base\n"
                "Knife eNB software in format:\n  * DNH0.0_ENB_2033939_1204:knife_tag",
            },
            "ap_version": {
                "metavar": "",
                "dest": "ap_version",
                "default": None,
                "type": str,
                "help": "Airphone software version",
            },
            "username": {
                "metavar": "",
                "dest": "username",
                "default": None,
                "type": str,
                "help": "Username of a user triggering test",
            },
            "ie": {
                "dest": "ignore_empty_suites",
                "action": "store_true",
                "help": "Flag set to determine if EmptySuiteException should be raised",
            },
            "tool": {
                "metavar": "",
                "dest": "tool",
                "default": None,
                "type": str,
                "help": "Tool that was used in test",
            },
            "qc_file": {
                "metavar": "QC Config File",
                "dest": "qc_config_file",
                "help": "Path to QC configuration file",
            },
            "sw_ver": {
                "metavar": "Software Version",
                "dest": "sw_version",
                "type": str,
                "help": "eNB software version in format:\n  * DNH0.0_ENB_2033939_1204\n  * DNH0.0_ENB_2033939_1204:base\n"
                "Knife eNB software in format:\n  * DNH0.0_ENB_2033939_1204:knife_tag",
            },
            "ute_version": {
                "metavar": "",
                "dest": "ute_version",
                "default": None,
                "type": str,
                "help": "Version of UTE package",
            },
            "nc": {
                "dest": "no_config",
                "action": "store_true",
                "help": "Flag set to determine if BTS config should be downloaded or not",
            },
            "env_issue": {
                "metavar": "",
                "dest": "env_issue",
                "type": str,
                "help": "Environment issue that occurred during test execution",
            },
            "fail_cause": {
                "metavar": "",
                "dest": "fail_cause",
                "type": str,
                "help": "Reason that caused test to fail",
            },
            "no_qc": {
                "dest": "no_qc",
                "action": "store_true",
                "help": "Flag set to determine if QC config should be sent",
            },
            "cu_build": {
                "dest": "cu_build",
                "default": "",
                "type": str,
                "help": "Central Unit version (provide when Distributed Unit is a System Under Test)",
            },
            "enb_nsa_build": {
                "dest": "enb_nsa_build",
                "default": "",
                "type": str,
                "help": "eNB NSA anchor version (provide when gNB is a System Under Test and NSA anchor is used)",
            },
            "gnb_nsa_build": {
                "dest": "gnb_nsa_build",
                "default": "",
                "type": str,
                "help": "gNB NSA anchor version (provide when eNB is a System Under Test and NSA anchor is used)",
            },
            "gnb_rf_shared_build": {
                "dest": "gnb_rf_shared_build",
                "default": "",
                "type": str,
                "help": "Provide when SBTS System Under Test shares an RU with an accompanying 5G RAT",
            },
            "enb_rf_shared_build": {
                "dest": "enb_rf_shared_build",
                "default": "",
                "type": str,
                "help": "Provide when SBTS System Under Test shares an RU with an accompanying 4G RAT",
            },
            "bts2g_rf_shared_build": {
                "dest": "bts2g_rf_shared_build",
                "default": "",
                "type": str,
                "help": "Provide when SBTS System Under Test shares an RU with an accompanying 2G RAT",
            },
            "nb_rf_shared_build": {
                "dest": "nb_rf_shared_build",
                "default": "",
                "type": str,
                "help": "Provide when SBTS System Under Test shares an RU with an accompanying 3G RAT",
            },
            "rfsw_build": {
                "dest": "rfsw_build",
                "default": "",
                "type": str,
                "help": "RF SW build version installed during TC execution",
            },
            "customers": {
                "dest": "customers",
                "nargs": "+",
                "default": None,
                "type": str,
                "help": "Customer entity for which the test case scenario is validated",
            },
            "rf_sw_line": {
                "dest": "rf_sw_line",
                "default": "",
                "type": str,
                "help": "Software line for which test case scenario is validated, example: CTA6",
            },
            "rf_sw_branch": {
                "dest": "rf_sw_branch",
                "default": "",
                "type": str,
                "help": "Software branch name for which test case scenario is validated, e.g., trunk/22R2/FB2109V",
            },
            "executed_test_loops": {
                "dest": "executed_test_loops",
                "type": int,
                "help": "Number of started test iterations (including setup). Refers to the Test Loops column in ReP",
                "required": False,
            },
            "cu_caas_build": {
                "dest": "cu_caas_build",
                "default": "",
                "type": str,
                "help": "Openshift Container Platform (OCP) SW version for CU",
            },
            "du_caas_build": {
                "dest": "du_caas_build",
                "default": "",
                "type": str,
                "help": "Openshift Container Platform (OCP) SW version for DU",
            },
            "fhgw_build": {
                "dest": "fhgw_build",
                "default": "",
                "type": str,
                "help": "Fronthaul Gateway SW version",
            },
        }

    def __getattr__(self, item):
        if item in self._params:
            return self._params[item]
        return None
